// Generated by scripts/generate-ios-contract.mts from src/contracts/mobile.ts and the types it names. Do not
// edit: run npm run generate:ios-contract. Values a newer computer may extend (statuses, engines, models,
// efforts, modes) are kept as strings, so an unknown one is shown as it was sent rather than failing
// the whole view.

import Foundation

/// A comparison's file list. Patches are fetched one at a time and never travel with the list.
enum DiffSummaryResult: Decodable, Equatable, Sendable {
    case available(range: DiffRange, files: [DiffFileSummary], additions: Int, deletions: Int)
    case unavailable(reason: String)
    case unknown
    case error(message: String)

    private enum CodingKeys: String, CodingKey { case status, range, files, additions, deletions, reason, message }

    init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        switch try container.decode(String.self, forKey: .status) {
        case "available": self = .available(range: try container.decode(DiffRange.self, forKey: .range), files: try container.decode([DiffFileSummary].self, forKey: .files), additions: try container.decode(Int.self, forKey: .additions), deletions: try container.decode(Int.self, forKey: .deletions))
        case "unavailable": self = .unavailable(reason: try container.decode(String.self, forKey: .reason))
        case "unknown": self = .unknown
        default: self = .error(message: try container.decodeIfPresent(String.self, forKey: .message) ?? "The comparison could not be read.")
        }
    }
}

/// One file's patch, as Git wrote it. `too-large` names the ceiling rather than truncating a patch.
enum DiffPatchResult: Decodable, Equatable, Sendable {
    case available(patch: String)
    case tooLarge
    case error(message: String)

    private enum CodingKeys: String, CodingKey { case status, patch, message }

    init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        switch try container.decode(String.self, forKey: .status) {
        case "available": self = .available(patch: try container.decode(String.self, forKey: .patch))
        case "too-large": self = .tooLarge
        default: self = .error(message: try container.decodeIfPresent(String.self, forKey: .message) ?? "The file could not be read.")
        }
    }
}

