/// Where a thread's runs happen, as the phone names it.
enum MobileLocation: Codable, Equatable, Sendable {
    case local
    case creating
    case releasing
    case worktree(name: String, threads: Int)

    private enum CodingKeys: String, CodingKey { case kind, name, threads }

    init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        switch try container.decode(String.self, forKey: .kind) {
        case "creating": self = .creating
        case "releasing": self = .releasing
        case "worktree": self = .worktree(name: try container.decode(String.self, forKey: .name), threads: try container.decodeIfPresent(Int.self, forKey: .threads) ?? 1)
        default: self = .local
        }
    }

    func encode(to encoder: Encoder) throws {
        var container = encoder.container(keyedBy: CodingKeys.self)
        switch self {
        case .local:
            try container.encode("local", forKey: .kind)
        case .creating:
            try container.encode("creating", forKey: .kind)
        case .releasing:
            try container.encode("releasing", forKey: .kind)
        case .worktree(let name, let threads):
            try container.encode("worktree", forKey: .kind)
            try container.encode(name, forKey: .name)
            try container.encode(threads, forKey: .threads)
        }
    }
}

