    var messages: [MobileMessage]
}

/// Why the server refused. The phone shows the message; the code decides whether it retries.
enum MobileErrorCode: String, Codable, Sendable {
    case expiredCode = "expired-code"
    case `internal`
    case rateLimited = "rate-limited"
    case unauthorized
    case unreadable
    case version
}

enum MobileClientMessage: Equatable, Sendable {
    case pair(code: String, deviceName: String)
    case resume(token: String, sessionId: String?, lastSequence: Int)
    case command(requestId: String, command: PhoneCommand)
    case query(requestId: String, query: MobileQuery)
    case pong(at: Double)
    case ping(at: Double)
    case pushToken(push: PhonePush?)

    var json: JSONValue {
        switch self {
        case .pair(let code, let deviceName): JSONValue.fields(["kind": .string("pair"), "version": JSONValue.number(Double(mobileProtocolVersion)), "oldestComputer": JSONValue.number(Double(oldestComputerProtocolVersion)), "code": JSONValue.string(code), "deviceName": JSONValue.string(deviceName)])
        case .resume(let token, let sessionId, let lastSequence): JSONValue.fields(["kind": .string("resume"), "version": JSONValue.number(Double(mobileProtocolVersion)), "oldestComputer": JSONValue.number(Double(oldestComputerProtocolVersion)), "token": JSONValue.string(token), "sessionId": sessionId.map { JSONValue.string($0) }, "lastSequence": JSONValue.number(Double(lastSequence))])
        case .command(let requestId, let command): JSONValue.fields(["kind": .string("command"), "requestId": JSONValue.string(requestId), "command": command.json])
        case .query(let requestId, let query): JSONValue.fields(["kind": .string("query"), "requestId": JSONValue.string(requestId), "query": query.json])
        case .pong(let at): JSONValue.fields(["kind": .string("pong"), "at": JSONValue.number(at)])
        case .ping(let at): JSONValue.fields(["kind": .string("ping"), "at": JSONValue.number(at)])
        case .pushToken(let push): JSONValue.fields(["kind": .string("push-token"), "push": push.map { $0.json } ?? .null])
        }
    }
}

/// One effort as a picker names it. `delegates` is an effort a coordinator never takes.
struct MobileEffortTerm: Codable, Equatable, Sendable {
    var id: String
    var label: String
    var description: String?
    var delegates: Bool?
}

/// One engine as this build names it: the modes a picker offers, in order, whether it has a fast
/// mode, and the models it ships knowing, which stand for its catalogue wherever `engines` sends none.
struct MobileEngineTerms: Codable, Equatable, Sendable {
    var id: String
    var label: String
    var fastMode: Bool
    var policies: [MobilePolicyTerm]
    var models: [MobileModel]
}

/// A mode a picker offers, as this build names it.
struct MobilePolicyTerm: Codable, Equatable, Sendable {
    var id: String
    var label: String
    var description: String
}

/// A role a thread may take, as this build names it.
struct MobileRoleTerm: Codable, Equatable, Identifiable, Sendable {
    var id: String
    var label: String
}

/// Everything a phone app reads by name from the build it is connected to.
struct MobileVocabulary: Codable, Equatable, Sendable {
    var engines: [MobileEngineTerms]
    /// Every effort, deepest first.
    var efforts: [MobileEffortTerm]
    /// Every role a thread may take, in menu order. Absent from older desktops.
    var roles: [MobileRoleTerm]?
}

enum MobileServerMessage: Equatable, Sendable {
    case paired(sequence: Int, deviceId: String, deviceName: String, token: String)
    case snapshot(sequence: Int, sessionId: String, view: MobileView, instance: String?, vocabulary: MobileVocabulary?, computer: String?, push: Bool = false)
    case patch(sequence: Int, patch: MobilePatch)
    case ack(sequence: Int, requestId: String, ok: Bool, message: String)
    case answer(sequence: Int, requestId: String, result: Result<JSONValue, MobileServerMessage.AnswerError>)
    case error(sequence: Int, code: MobileErrorCode, message: String)
    case ping(sequence: Int, at: Double)

    var sequence: Int {
        switch self {
        case .paired(let sequence, _, _, _), .snapshot(let sequence, _, _, _, _, _, _), .patch(let sequence, _), .ack(let sequence, _, _, _), .answer(let sequence, _, _), .error(let sequence, _, _), .ping(let sequence, _):
            sequence
        }
    }
}

extension MobileServerMessage {
    /// The message a frame of `kind` holds, or nil for one this app does not know or a required field that does not read.
    static func read(kind: String, sequence: Int, _ object: [String: JSONValue]) -> MobileServerMessage? {
        switch kind {
        case "paired":
            guard let deviceId = object["deviceId"]?.stringValue, let deviceName = object["deviceName"]?.stringValue, let token = object["token"]?.stringValue else { return nil }
            return .paired(sequence: sequence, deviceId: deviceId, deviceName: deviceName, token: token)
        case "snapshot":
            guard let sessionId = object["sessionId"]?.stringValue, let view = object["view"].flatMap({ try? $0.decode(MobileView.self) }) else { return nil }
            return .snapshot(sequence: sequence, sessionId: sessionId, view: view, instance: object["instance"]?.stringValue, vocabulary: object["vocabulary"].flatMap({ try? $0.decode(MobileVocabulary.self) }), computer: object["computer"]?.stringValue, push: object["push"] == .bool(true))
        case "patch":
            guard let patch = object["patch"].flatMap({ try? $0.decode(MobilePatch.self) }) else { return nil }
            return .patch(sequence: sequence, patch: patch)
        case "ack":
            guard let requestId = object["requestId"]?.stringValue, let ok = object["ok"]?.boolValue else { return nil }
            return .ack(sequence: sequence, requestId: requestId, ok: ok, message: object["message"]?.stringValue ?? "")
        case "answer":
            guard let requestId = object["requestId"]?.stringValue, case .bool(let ok) = object["ok"] else { return nil }
            return .answer(sequence: sequence, requestId: requestId, result: ok ? .success(object["result"] ?? .null) : .failure(.init(message: object["message"]?.stringValue ?? "")))
        case "error":
            guard let code = object["code"]?.stringValue.flatMap(MobileErrorCode.init(rawValue:)) else { return nil }
            return .error(sequence: sequence, code: code, message: object["message"]?.stringValue ?? "")
        case "ping":
            guard let at = object["at"]?.numberValue else { return nil }
            return .ping(sequence: sequence, at: at)
        default:
            return nil
        }
    }
}

