/// Where a drafted annotation stays visible until the send that carries it.
enum AnnotationAnchor: Codable, Equatable, Sendable {
    case message(messageId: String, start: Double, end: Double)
    case diff(comparison: String, path: String, start: String, end: String, side: String)

    private enum CodingKeys: String, CodingKey { case kind, messageId, start, end, comparison, path, side }

    init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        switch try container.decode(String.self, forKey: .kind) {
        case "message": self = .message(messageId: try container.decode(String.self, forKey: .messageId), start: try container.decode(Double.self, forKey: .start), end: try container.decode(Double.self, forKey: .end))
        case "diff": self = .diff(comparison: try container.decode(String.self, forKey: .comparison), path: try container.decode(String.self, forKey: .path), start: try container.decode(String.self, forKey: .start), end: try container.decode(String.self, forKey: .end), side: try container.decode(String.self, forKey: .side))
        default: throw DecodingError.dataCorruptedError(forKey: .kind, in: container, debugDescription: "Unknown kind")
        }
    }

    func encode(to encoder: Encoder) throws {
        var container = encoder.container(keyedBy: CodingKeys.self)
        switch self {
        case .message(let messageId, let start, let end):
            try container.encode("message", forKey: .kind)
            try container.encode(messageId, forKey: .messageId)
            try container.encode(start, forKey: .start)
            try container.encode(end, forKey: .end)
        case .diff(let comparison, let path, let start, let end, let side):
            try container.encode("diff", forKey: .kind)
            try container.encode(comparison, forKey: .comparison)
            try container.encode(path, forKey: .path)
            try container.encode(start, forKey: .start)
            try container.encode(end, forKey: .end)
            try container.encode(side, forKey: .side)
        }
    }

    var json: JSONValue {
        switch self {
        case .message(let messageId, let start, let end): JSONValue.fields(["kind": .string("message"), "messageId": JSONValue.string(messageId), "start": JSONValue.number(start), "end": JSONValue.number(end)])
        case .diff(let comparison, let path, let start, let end, let side): JSONValue.fields(["kind": .string("diff"), "comparison": JSONValue.string(comparison), "path": JSONValue.string(path), "start": JSONValue.string(start), "end": JSONValue.string(end), "side": JSONValue.string(side)])
        }
    }
}

