    var deletions: Int
    var binary: Bool
}

/// What the panel is comparing. `uncommitted` is the working tree against HEAD, which is the shape a
/// thread's own edits have before anything is committed. `branches` compares from where the two sides
/// last agreed, the way a pull request reads, and a null `compare` means the working tree itself.
enum DiffRange: Codable, Equatable, Hashable, Sendable {
    case uncommitted
    case commit(commit: String)
    case branches(base: String, compare: String?)

    private enum CodingKeys: String, CodingKey { case kind, commit, base, compare }

    init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        switch try container.decode(String.self, forKey: .kind) {
        case "commit": self = .commit(commit: try container.decode(String.self, forKey: .commit))
        case "branches": self = .branches(base: try container.decode(String.self, forKey: .base), compare: try container.decodeIfPresent(String.self, forKey: .compare))
        default: self = .uncommitted
        }
    }

    func encode(to encoder: Encoder) throws {
        var container = encoder.container(keyedBy: CodingKeys.self)
        switch self {
        case .uncommitted:
            try container.encode("uncommitted", forKey: .kind)
        case .commit(let commit):
            try container.encode("commit", forKey: .kind)
            try container.encode(commit, forKey: .commit)
        case .branches(let base, let compare):
            try container.encode("branches", forKey: .kind)
            try container.encode(base, forKey: .base)
            if let compare { try container.encode(compare, forKey: .compare) } else { try container.encodeNil(forKey: .compare) }
        }
    }

    var json: JSONValue {
        switch self {
        case .uncommitted: JSONValue.fields(["kind": .string("uncommitted")])
        case .commit(let commit): JSONValue.fields(["kind": .string("commit"), "commit": JSONValue.string(commit)])
        case .branches(let base, let compare): JSONValue.fields(["kind": .string("branches"), "base": JSONValue.string(base), "compare": compare.map { JSONValue.string($0) } ?? .null])
        }
    }
}

/// Geometry is normalized to 0..1 of the image so it survives resizing and exports at native resolution.
/// A box spans (x, y) to (x + width, y + height) with non-negative extents; an arrow runs from its tail at
/// (x, y) to its tip at (x + width, y + height), so its extents are signed.
struct ImageAnnotation: Codable, Equatable, Sendable {
    var kind: String
    var x: Double
    var y: Double
    var width: Double
    var height: Double
    var text: String
}

extension ImageAnnotation {
    var json: JSONValue {
        JSONValue.fields(["kind": JSONValue.string(kind), "x": JSONValue.number(x), "y": JSONValue.number(y), "width": JSONValue.number(width), "height": JSONValue.number(height), "text": JSONValue.string(text)])
    }
}

